#!/usr/bin/env python3
"""Reader-facing Patterns index; preserves the existing seven study URLs."""
from pathlib import Path
import json,html
from urllib.parse import quote
R=Path(__file__).resolve().parents[1]
load=lambda p:json.loads((R/p).read_text())
e=lambda s:html.escape(str(s),quote=True)
stories=load('data/pattern-stories.json'); sites={s['n']:s for s in load('data/sites.json')}
videos=load('data/videos.json');creators=load('data/creators.json')
features_catalog=load('data/pattern-features.json')
parts=[]
for number,story in enumerate(stories,1):
    examples=[]
    for name in story['sites']:
        assert name in sites,name
        films=videos.get(name,[])
        keys=list(dict.fromkeys(v.get('cr') for v in films if v.get('cr') in creators))
        credits=' · '.join('<a href="https://www.youtube.com/'+e(creators[k]['handle'])+'" target="_blank" rel="noopener">'+e(creators[k]['name'])+' ↗</a>' for k in keys)
        examples.append('<li><a class="place" href="/?site='+quote(name)+'">'+e(name)+' →</a><small>'+str(len(films))+' films'+('</small><div class="credits">'+credits+'</div>' if keys else '</small>')+'</li>')
    features=[p for p in features_catalog if p['group']==story['theme']]
    definitions=''.join('<dt>'+e(p['label'])+'</dt><dd>'+e(p['definition'])+'</dd>' for p in features)
    parts.append('<article id="'+story['id']+'"><div class="number">'+str(number).zfill(2)+' / '+e(story['theme'])+'</div><h2>'+e(story['title'])+'</h2>'+''.join('<p>'+e(p)+'</p>' for p in story['paragraphs'])+'<h3>See it through the creators</h3><ul>'+''.join(examples)+'</ul><details><summary>What to look for</summary><dl>'+definitions+'</dl></details></article>')
nav=''.join('<a href="#'+s['id']+'">'+e(s['theme'])+'</a>' for s in stories)

feature_cards=[]
theme_ids={s['theme']:s['id'] for s in stories}
theme_accents={'Making space':'moss','Working stone':'gold','Supporting life':'ocean','Organizing movement':'clay','Remembering & expressing':'rose','Orienting in place & time':'violet','Changing over time':'moss'}
last_theme=None
for feature in features_catalog:
    theme=feature['group']
    if theme!=last_theme:
        feature_cards.append('<h3 class="feature-group-heading" data-group="'+e(theme)+'">'+e(theme)+'</h3>')
        last_theme=theme
    feature_cards.append('<article class="feature-card" id="feature-'+e(feature['id'])+'" data-theme="'+e(theme)+'" data-accent="'+e(theme_accents[theme])+'"><span class="feature-glyph-frame"><img class="feature-glyph" src="'+e(feature['glyph'])+'" width="88" height="88" alt="" loading="lazy"></span><small>'+e(theme)+'</small><h3>'+e(feature['label'])+'</h3><p>'+e(feature['definition'])+'</p><a href="#'+theme_ids[theme]+'">Compare places &amp; meet the creators →</a></article>')
feature_section='<section aria-labelledby="features-heading" class="feature-browser"><h2 id="features-heading">24 ways to look closer</h2><p>Seven themes, each with its own color. Choose a feature, then follow its theme to places, films and the people who bring them into view.</p><div class="feature-controls"><label for="feature-search">Find a feature<input id="feature-search" type="search" placeholder="Water, underground, stone…"></label><label for="feature-theme">Theme<select id="feature-theme"><option value="">All themes</option>'+''.join('<option>'+e(s['theme'])+'</option>' for s in stories)+'</select></label></div><p id="feature-count" role="status">24 features</p><div class="feature-grid">'+''.join(feature_cards)+'</div><p id="feature-empty" hidden>No matching features. Try another word or choose all themes.</p></section><div class="editorial-heading"><span class="kicker">The correspondences</span><h2>Seven short readings across places</h2></div>'

page='''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Patterns across places — Ancient Atlas</title><meta name="description" content="Short field notes on the ideas that recur across the Ancient Atlas. Compare places, watch their creators, and look closer."><link rel="canonical" href="https://theancientatlas.com/patterns/"><style>
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:#17191b;color:#f0eee9;font:16px/1.7 system-ui,sans-serif}header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px max(24px,calc((100vw - 1100px)/2));border-bottom:1px solid #414344;flex-wrap:wrap}a{color:#e1c77f;text-underline-offset:4px}header>a{color:#f0eee9;text-decoration:none;font:24px Georgia}header nav{display:flex;gap:20px;align-items:center}main{max-width:1100px;margin:auto;padding:54px 24px}.intro{max-width:760px}.kicker,.number{font:12px/1.5 system-ui;letter-spacing:.09em;text-transform:uppercase;color:#9fd2c6}h1{font:clamp(40px,6vw,68px)/1.05 Georgia;margin:20px 0}h2{font:32px/1.15 Georgia;margin:16px 0 24px}h3{font-size:13px;margin:26px 0 12px;color:#eeeae2}p{color:#d1d0cc}.intro p{font-size:19px}.themes{display:flex;flex-wrap:wrap;gap:8px;margin:32px 0 48px}.themes a{padding:8px 12px;border:1px solid #555b5c;border-radius:20px;color:#d1dcda;font-size:13px;text-decoration:none}.stories{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:28px}article{border-top:2px solid #68b3a0;padding:24px 0;scroll-margin-top:24px}article p{font-size:16px}ul{padding:0;list-style:none}li{padding:12px 0;border-top:1px solid #383c3e}.place{display:block;font-weight:600}small,.credits{font-size:12px;color:#afb5b5}.credits a{color:#a8d4e4}summary{cursor:pointer;color:#c2cfcc;font-size:14px;min-height:44px;padding:10px 0}dt{font-weight:600;font-size:14px}dd{margin:0 0 12px;color:#bfc5c4;font-size:14px}.method{border-top:1px solid #555;padding-top:28px;margin-top:30px;max-width:780px;font-size:14px}a:focus-visible,summary:focus-visible{outline:2px solid #e1c77f;outline-offset:4px}@media(max-width:700px){.stories{grid-template-columns:1fr}main{padding:32px 22px}header{padding:14px 22px}header nav{flex-wrap:wrap}}
.feature-browser{margin-bottom:64px}.feature-controls{display:flex;gap:20px;flex-wrap:wrap}.feature-controls label{display:grid;gap:6px;font-size:13px;flex:1;min-width:200px}.feature-controls input,.feature-controls select{width:100%;padding:12px;border-radius:8px;border:1px solid #687170;background:#222729;color:#f0eee9;font:16px system-ui}.feature-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.feature-card{padding:22px;border:1px solid #475350;border-radius:14px;background:linear-gradient(140deg,#20332f,#202b35);display:flex;flex-direction:column}.feature-card[hidden]{display:none}.feature-card h3{font:23px/1.2 Georgia;margin:10px 0}.feature-card p{font-size:14px;flex:1}.feature-card>a{font-size:13px;min-height:44px;padding-top:12px}.feature-card[data-accent="rose"]{--feature-accent:#d5a0a0;--feature-tint:#382d31}.feature-card small{color:#9fd2c6}.editorial-heading{margin:30px 0}.feature-controls :focus-visible{outline:2px solid #e1c77f;outline-offset:3px}@media(max-width:900px){.feature-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:540px){.feature-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}}
.feature-group-heading{grid-column:1/-1;margin:24px 0 0;font:22px Georgia;color:#eeeae2}.feature-group-heading[hidden]{display:none}.feature-glyph-frame{display:block;position:relative;width:88px;height:88px;overflow:hidden;border-radius:19px;margin:0 0 18px;background:var(--feature-tint);box-shadow:0 3px 10px #0002}.feature-glyph{display:block;position:absolute;width:105px;height:105px;max-width:none;left:-8.5px;top:-8.5px}.feature-card{border-top:2px solid var(--feature-accent,#7B9F8E);background:linear-gradient(145deg,var(--feature-tint,#23332f),#202426 75%)}.feature-card[data-accent="moss"]{--feature-accent:#8fbaa5;--feature-tint:#263c34}.feature-card[data-accent="ocean"]{--feature-accent:#83bdd4;--feature-tint:#243942}.feature-card[data-accent="clay"]{--feature-accent:#d29578;--feature-tint:#3b2e29}.feature-card[data-accent="violet"]{--feature-accent:#ae9ed2;--feature-tint:#322c40}.feature-card[data-accent="gold"]{--feature-accent:#d9bd70;--feature-tint:#393426}.feature-card[data-accent="rose"]{--feature-accent:#d5a0a0;--feature-tint:#382d31}.feature-card small{color:var(--feature-accent)}.feature-card>a{color:var(--feature-accent)}
</style></head><body><header><a href="/">Ancient Atlas</a><nav aria-label="Primary"><a href="/">Back to map</a><a href="/library/">Articles</a><a href="/creators/">Creators</a></nav></header><main><div class="intro"><div class="kicker">Patterns · What connects places</div><h1>What people<br>made possible.</h1><p>How do you make space, move water, bring people together, or leave something behind? Across the Atlas, familiar problems take strikingly different forms.</p><p>Browse 24 features of the built world, from underground spaces to water channels. See how they connect across places, then follow the creators onto the ground.</p></div><nav class="themes" aria-label="Pattern themes">'''+nav+'''</nav>'''+feature_section+'''<section class="stories">'''+''.join(parts)+'''</section><section class="method"><h2>Comparison is a beginning.</h2><p>These are editorial readings of a curated collection, not a representative survey of all ancient societies. Similar forms can arise through shared constraints, exchange or independent choices. Each explanation needs local evidence.</p><p>The underlying research screened 693 site descriptions and proposed 24 features. These notes do not automatically assign badges to sites or claim that every linked film shows every feature.</p><p>Context: <a href="https://whc.unesco.org/en/list/357/">Cappadocia</a>, <a href="https://whc.unesco.org/en/list/18/">Lalibela</a>, <a href="https://whc.unesco.org/document/168269">Petra’s water systems</a>, and <a href="https://www.worldheritageireland.ie/world-heritage-properties/bru-na-boinne/historical-background/">Newgrange’s seasonal light</a>. For the older technical studies: <a href="/patterns/polygonal/">Polygonal masonry</a> · <a href="/patterns/precision/">Precision</a> · <a href="/patterns/scale/">Scale</a> · <a href="/patterns/machining/">Working marks</a> · <a href="/patterns/hardness/">Materials</a> · <a href="/patterns/geometry/">Geometry</a> · <a href="/patterns/stratigraphy/">Building phases</a>. Those studies retain their existing arguments and are being reviewed separately.</p></section></main><script>
const search=document.getElementById('feature-search'),filter=document.getElementById('feature-theme');
function filterFeatures(){let count=0;document.querySelectorAll('.feature-card').forEach(card=>{const matches=(!filter.value||card.dataset.theme===filter.value)&&card.textContent.toLowerCase().includes(search.value.trim().toLowerCase());card.hidden=!matches;if(matches)count++;});document.getElementById('feature-count').textContent=count+' of 24 features';document.getElementById('feature-empty').hidden=count!==0;document.querySelectorAll('.feature-group-heading').forEach(h=>h.hidden=![...document.querySelectorAll('.feature-card')].some(c=>!c.hidden&&c.dataset.theme===h.dataset.group));}
search.addEventListener('input',filterFeatures);filter.addEventListener('change',filterFeatures);
</script></body></html>'''
(R/'public/patterns/index.html').write_text(page)
print('Built Patterns: 7 editorial notes, 24 feature definitions, 21 site links')
